 "content": "def transform(grid):
    """For each nonzero source cell, place a copy of the 3x3 mask centered on it.

    The source mask's nonzero positions are copied in the source color; overlapping
    copies simply retain that color.
    """
    n, m = len(grid), len(grid[0])
    out = [[0 for _ in range(3*m)] for _ in range(3*n)]
    for r in range(n):
        for c in range(m):
            color = grid[r][c]
            if color:
